"""Pick the A2A server config source for the engine that is running.

CALM reads the ``a2a_server`` block of ``endpoints.yml``; Mantle reads the
top-level ``a2a_server`` block of ``integrations.yml``. The choice is made from
the model's ``engine_version``, so A2A is only fully started once the model has
loaded and the matching source has produced :class:`A2AServerSettings`.
``rasa.mantle`` is imported lazily, like channel loading, so a CALM run never
loads the Mantle package.
"""

from __future__ import annotations

from pathlib import Path
from typing import TYPE_CHECKING, Mapping, Optional, Union

import structlog

from rasa.core.a2a_server.config import (
    A2A_SERVER_KEY,
    A2AConfigSource,
    A2AServerConfig,
    A2AServerSettings,
    a2a_server_files_for_engine,
    validate_a2a_server_session_config_or_raise,
)
from rasa.exceptions import ValidationError
from rasa.shared.constants import DEFAULT_ENDPOINTS_PATH
from rasa.shared.engine_version import (
    CALM_ENGINE_VERSION,
    MANTLE_ENGINE_VERSION,
    dispatch_by_engine_version,
)
from rasa.shared.project_structure import MANTLE_INTEGRATIONS_FILE
from rasa.shared.utils.yaml import read_yaml_file

if TYPE_CHECKING:
    from rasa.core.a2a_server.startup import A2AServerStartup
    from rasa.core.config.available_endpoints import AvailableEndpoints
    from rasa.core.processor import MessageProcessor

structlogger = structlog.get_logger()


class CalmA2AConfigSource(A2AConfigSource):
    """Reads the ``a2a_server`` block of ``endpoints.yml`` (already parsed)."""

    engine_version = CALM_ENGINE_VERSION
    file_name = DEFAULT_ENDPOINTS_PATH

    def __init__(self, endpoints: Optional["AvailableEndpoints"]) -> None:
        """Wrap the ``a2a_server`` block already parsed into *endpoints*."""
        self._config = endpoints.a2a_server if endpoints is not None else None

    @property
    def config(self) -> Optional[A2AServerConfig]:
        """Parsed block, or ``None`` when ``endpoints.yml`` has no ``a2a_server``."""
        return self._config

    def is_declared(self) -> bool:
        """Whether ``endpoints.yml`` has an ``a2a_server`` block."""
        return self._config is not None

    def load(self) -> Optional[A2AServerSettings]:
        """Return engine-neutral settings, or ``None`` when the block is absent."""
        if self._config is None:
            return None
        return self._config.to_settings()

    def to_startup(self, settings: A2AServerSettings) -> "A2AServerStartup":
        """Carry the CALM repair option on the CALM startup type."""
        from rasa.core.a2a_server.startup import CalmA2AServerStartup

        config = self._config
        return CalmA2AServerStartup(
            engine_version=self.engine_version,
            settings=settings,
            include_conversation_repair=(
                config.include_conversation_repair if config is not None else True
            ),
        )


def resolved_a2a_project_root(project_root: Union[str, Path, None] = None) -> Path:
    """Directory that holds the engine's A2A file.

    An explicit root wins. Otherwise the CLI cascade applies:
    ``RASA_PROJECT_FOLDER``, then the working directory.
    """
    if project_root is not None:
        return Path(project_root)
    from rasa.cli.project_env import resolve_project_dir

    return resolve_project_dir()


def resolve_agent_card_against_project(
    settings: Optional[A2AServerSettings], project_root: Path
) -> Optional[A2AServerSettings]:
    """Resolve a relative ``agent_card_path`` against *project_root*."""
    if settings is None or not settings.agent_card_path:
        return settings
    card_path = Path(settings.agent_card_path)
    if card_path.is_absolute():
        return settings
    return settings.model_copy(
        update={"agent_card_path": str((project_root / card_path).resolve())}
    )


def select_a2a_config_source(
    engine_version: str,
    *,
    endpoints: Optional["AvailableEndpoints"],
    project_root: Union[str, Path, None] = None,
) -> A2AConfigSource:
    """Return the config source that matches *engine_version*."""
    root = resolved_a2a_project_root(project_root)

    def _mantle_source() -> A2AConfigSource:
        from rasa.mantle.config.a2a_server import MantleA2AConfigSource

        return MantleA2AConfigSource(root)

    return dispatch_by_engine_version(
        engine_version,
        calm_v1_handler=lambda: CalmA2AConfigSource(endpoints),
        mantle_handler=_mantle_source,
    )


def resolve_a2a_server_settings(
    engine_version: str,
    *,
    endpoints: Optional["AvailableEndpoints"],
    project_root: Union[str, Path, None] = None,
) -> Optional[A2AServerSettings]:
    """Resolve A2A server settings from the source that matches *engine_version*.

    The other engine's block, if present, is ignored with a warning that points
    at the file this engine reads.

    Args:
        engine_version: Engine of the model being served.
        endpoints: Parsed ``endpoints.yml`` (CALM source).
        project_root: Directory holding ``integrations.yml`` (Mantle source).
            When omitted, ``RASA_PROJECT_FOLDER`` then the working directory.

    Returns:
        Settings when the matching source enables A2A, else ``None``.
    """
    root = resolved_a2a_project_root(project_root)
    source = select_a2a_config_source(
        engine_version, endpoints=endpoints, project_root=root
    )
    settings = resolve_agent_card_against_project(source.load(), root)
    warn_if_other_engine_declares_a2a_server(
        engine_version, endpoints=endpoints, project_root=root
    )
    return settings


def validate_a2a_server_for_loaded_model_or_raise(
    processor: Optional["MessageProcessor"],
    *,
    endpoints: Optional["AvailableEndpoints"],
    project_root: Union[str, Path, None] = None,
) -> Optional[A2AServerSettings]:
    """Resolve A2A settings for a just-loaded model and check its session config.

    For entry points that load a model without binding an A2A startup object
    (``rasa shell``, tests, model pulls). The config source follows the
    processor's ``engine_version``; when that source enables A2A, the engine's
    session config must not start a new session after expiry (see
    :func:`~rasa.core.a2a_server.config.validate_a2a_server_session_config_or_raise`).
    ``rasa run`` does not call this: it checks the settings it already bound in
    :func:`~rasa.core.a2a_server.startup.bind_a2a_server_to_loaded_model`.

    Returns:
        The resolved settings, or ``None`` when A2A is off for this engine.
    """
    if processor is None:
        return None

    engine_version = processor.engine_version
    settings = resolve_a2a_server_settings(
        engine_version,
        endpoints=endpoints,
        project_root=resolved_a2a_project_root(project_root),
    )
    validate_a2a_server_session_config_or_raise(
        settings, processor.session_config, engine_version=engine_version
    )
    return settings


def validate_a2a_server_engine_or_raise(
    *,
    bound_engine_version: str,
    loaded_engine_version: str,
) -> None:
    """Fail A2A startup when the config source and the loaded model disagree.

    Routes and bearer auth are bound from the project layout before the model
    loads. If the model then reports another engine, the bound settings came
    from the wrong file, so A2A must not start.

    Raises:
        ValidationError: ``validation.a2a_server.engine_mismatch``.
    """
    if bound_engine_version == loaded_engine_version:
        return

    bound_file, _ = a2a_server_files_for_engine(bound_engine_version)
    loaded_file, _ = a2a_server_files_for_engine(loaded_engine_version)
    raise ValidationError(
        code="validation.a2a_server.engine_mismatch",
        bound_engine_version=bound_engine_version,
        loaded_engine_version=loaded_engine_version,
        event_info=(
            f"The `{A2A_SERVER_KEY}` block was read from `{bound_file}` for the "
            f"'{bound_engine_version}' engine, but the loaded model runs on "
            f"'{loaded_engine_version}', which reads `{A2A_SERVER_KEY}` from "
            f"`{loaded_file}`. Retrain the model to match the project layout, or "
            f"move the `{A2A_SERVER_KEY}` block to `{loaded_file}`."
        ),
    )


def integrations_file_declares_a2a_server(
    project_root: Union[str, Path, None] = None,
) -> bool:
    """Whether ``integrations.yml`` under *project_root* has an ``a2a_server`` key.

    Only key presence matters, so ``${VAR}`` references are not expanded and an
    unset variable elsewhere in the file cannot raise. Kept in the core so a
    CALM run can warn about a stray Mantle block without importing
    ``rasa.mantle``.
    """
    root = resolved_a2a_project_root(project_root)
    integrations_file = root / MANTLE_INTEGRATIONS_FILE
    if not integrations_file.is_file():
        return False
    raw = read_yaml_file(integrations_file, expand_env_vars=False)
    return isinstance(raw, Mapping) and raw.get(A2A_SERVER_KEY) is not None


def warn_if_other_engine_declares_a2a_server(
    engine_version: str,
    *,
    endpoints: Optional["AvailableEndpoints"],
    project_root: Union[str, Path, None] = None,
) -> None:
    """Warn when the other engine's file carries a stray ``a2a_server`` block."""
    if engine_version == MANTLE_ENGINE_VERSION:
        other_declared = CalmA2AConfigSource(endpoints).is_declared()
        other_file = DEFAULT_ENDPOINTS_PATH
    else:
        other_declared = integrations_file_declares_a2a_server(project_root)
        other_file = MANTLE_INTEGRATIONS_FILE
    if not other_declared:
        return

    active_file, _ = a2a_server_files_for_engine(engine_version)
    structlogger.warning(
        "a2a_server.config.other_engine_block_ignored",
        engine_version=engine_version,
        ignored_file=other_file,
        event_info=(
            f"The `{A2A_SERVER_KEY}` block in `{other_file}` is ignored for the "
            f"'{engine_version}' engine. Configure `{A2A_SERVER_KEY}` in "
            f"`{active_file}` instead."
        ),
    )
